-- ============================================
-- LUMA — Thème 17 : MOYEN 1/3 x4 — Un essai pour rejoindre une équipe locale
-- ============================================


update scenarios set content = '{"characters": {"coach": "l''entraîneur de l''équipe", "teammate": "un coéquipier"}, "start_node": "n1", "nodes": {"n1": {"speaker": "coach", "text": "Welcome to tryouts! What position do you usually play?", "text_fr": "Bienvenue aux essais ! Quel poste jouez-vous habituellement ?", "choices": [{"text": "Midfield, I like controlling the pace of the game.", "text_fr": "Milieu de terrain, j''aime contrôler le rythme du jeu.", "next": "n2"}, {"text": "Honestly, I''m flexible, wherever the team needs me.", "text_fr": "Honnêtement, je suis flexible, où que l''équipe ait besoin de moi.", "next": "n2b"}]}, "n2": {"speaker": "coach", "text": "Good, we actually need more depth there. Let''s see what you''ve got.", "text_fr": "Bien, on a justement besoin de plus de profondeur là. Voyons ce que vous avez.", "choices": [{"text": "(play with focus and confidence during the tryout)", "text_fr": "(joue avec concentration et confiance pendant l''essai)", "next": "n3"}]}, "n2b": {"speaker": "coach", "text": "I appreciate that flexibility, it''s valuable for a squad.", "text_fr": "J''apprécie cette flexibilité, c''est précieux pour une équipe.", "choices": [{"text": "(play with focus and confidence during the tryout)", "text_fr": "(joue avec concentration et confiance pendant l''essai)", "next": "n3"}]}, "n3": {"speaker": "coach", "text": "That was a strong opening drill. Let''s see how you handle a scrimmage.", "text_fr": "C''était un bon exercice d''ouverture. Voyons comment tu gères un match d''entraînement.", "choices": [{"text": "I''m ready, let''s do this.", "text_fr": "Je suis prêt, allons-y.", "next": "n4"}]}, "n4": {"speaker": "teammate", "text": "(During scrimmage) Nice pass! You''ve got good vision on the field.", "text_fr": "(Pendant le match d''entraînement) Belle passe ! T''as une bonne vision du terrain.", "choices": [{"text": "Thanks, trying to stay aware of everyone''s positioning.", "text_fr": "Merci, j''essaie de rester conscient du positionnement de tous.", "next": "n5"}]}, "n5": {"speaker": "coach", "text": "That was a strong session. We''d like to offer you a spot on the team.", "text_fr": "C''était une session solide. On aimerait vous offrir une place dans l''équipe.", "choices": [{"text": "That means a lot, thank you, I''m in!", "text_fr": "Ça compte beaucoup, merci, je suis partant !", "next": "n6"}]}, "n6": {"speaker": "teammate", "text": "Welcome to the squad! First training is Tuesday, don''t be late.", "text_fr": "Bienvenue dans l''équipe ! Premier entraînement mardi, sois pas en retard.", "choices": [{"text": "I''ll definitely be there, looking forward to it.", "text_fr": "Je serai définitivement là, j''ai hâte.", "next": "n7"}]}, "n7": {"speaker": "coach", "text": "Great attitude, that''s exactly what we look for in this team.", "text_fr": "Excellente attitude, c''est exactement ce qu''on recherche dans cette équipe.", "choices": [{"text": "Thank you for the opportunity, I won''t take it for granted.", "text_fr": "Merci pour l''opportunité, je vais pas la prendre pour acquise.", "next": "end_joined"}]}, "end_joined": {"speaker": "coach", "text": "Welcome to the team, first training is Tuesday!", "text_fr": "Bienvenue dans l''équipe, premier entraînement mardi !", "end": true, "ending_label": "Équipe locale rejointe avec succès 🏆⚽"}}}'::jsonb, is_playable = true
where title = 'Un essai pour rejoindre une équipe locale'
  and theme_id = (select id from scenario_themes where position = 17 and language_id = (select id from languages where code = 'en'));
